        byte = data[i]
        if byte < 0x80:
            char_len = 1
        elif byte < 0xC0:
            break
        elif byte < 0xE0:
            char_len = 2
        elif byte < 0xF0:
            char_len = 3
        elif byte < 0xF8:
            char_len = 4
        else:
            break
        if i + char_len > max_n:
            break
        valid = True
        for j in range(1, char_len):
            if i + j >= n:
                valid = False
                break
            next_byte = data[i + j]
            if not (0x80 <= next_byte < 0xC0):
                valid = False
                break
        if not valid:
            break
        result.append(data[i:i+char_len])
        i += char_len
    return b''.join(result)
